#include <iostream>
#include <vector>
#include <utility>
#include <algorithm>

using namespace std;

// product_j が product_i の上位互換か判定する
bool is_strictly_superior(const pair<int, vector<int>> &product_i, const pair<int, vector<int>> &product_j) {
    const auto&[price_i, feature_i]{product_i};
    const auto&[price_j, feature_j]{product_j};

    return price_i >= price_j &&
           includes(feature_j.begin(), feature_j.end(), feature_i.begin(), feature_i.end()) &&
           (price_i > price_j || !includes(feature_i.begin(), feature_i.end(), feature_j.begin(), feature_j.end()));
}

// products に上位互換の組があるか判定する
bool has_superior_pair(const vector<pair<int, vector<int>>> &products) {
    return any_of(products.begin(), products.end(), [&products](const auto &product_i) {
        return any_of(products.begin(), products.end(), [&product_i](const auto &product_j) {
            return is_strictly_superior(product_i, product_j);
        });
    });
}

int main() {
    int N, M;
    cin >> N >> M;
    vector<pair<int, vector<int>>> products(N);
    for (auto&&[price, feature] : products) {
        cin >> price;
        int K;
        cin >> K;
        feature = vector<int>(K);
        for (auto &&f : feature)
            cin >> f;
    }

    cout << (has_superior_pair(products) ? "Yes" : "No") << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;

int main(void){
    int N,M;
    cin >> N >> M;
    int P[N];
    bool func[N][M]={}; //func[i][j]:i番目の商品がj番目の機能を持つか(0-indexed)
    for(int i=0;i<N;i++){
        cin >> P[i];
        int c;
        cin >> c;
        for(int j=0;j<c;j++){
            int f;
            cin >> f;
            f--; //0-indexedに直す
            func[i][f]=true;
        }
    }
    bool ans=false; //条件をすべて満たす(i,j)のペアが存在するか
    for(int i=0;i<N;i++){
        for(int j=0;j<N;j++){
            bool cond1=false; //P_i>=P_jかどうか
            bool cond2=true; //j番目の製品がi番目の製品が持つ機能をすべてもつかどうか
            bool cond3=false; //P_i>P_jである、またはj番目の製品がi番目の製品にない機能を1つ以上もつかどうか
            if(P[i]>=P[j]) cond1=true;
            for(int k=0;k<M;k++){
                if(func[i][k] && !func[j][k]) cond2=false; //i番目の製品がもつ機能をj番目の製品が持っていなかったらダメ
            }
            if(P[i]>P[j]) cond3=true;
            for(int k=0;k<M;k++){
                if(func[j][k] && !func[i][k]) cond3=true; //j番目の製品がi番目の製品にない機能をもっていたらOK
            }
            if(cond1 && cond2 && cond3) ans=true;
        }
    }
    if(ans==true) cout << "Yes" << endl;
    else cout << "No" << endl;
}
